36: /**
37:  * Settings patches recursively merge records. Explicit nulls are necessary to
38:  * remove omitted fields and deleted map entries, including across JSON hosts
39:  * where undefined disappears before the patch reaches the settings service.
40:  * Override editors pass their narrower field list so plugin-owned identity is
41:  * never included in the resulting patch.
42:  */
43: export function buildMcpSettingsPatch(
44:   next: McpSettingsPatchInput,
45:   previous: McpSettingsPatchInput = {},
46:   fields: readonly McpSettingsField[] = MCP_SERVER_SETTINGS_FIELDS,
47: ): Record<string, unknown> {
48:   return Object.fromEntries(
49:     fields.map((field) => {
50:       const value = next[field];
51:       if (value === undefined) return [field, null];
52:       if (field === "env" || field === "headers" || field === "envHeaders") {
53:         const incoming = next[field]!;
54:         const removed = Object.keys(previous[field] ?? {})
55:           .filter((key) => !Object.hasOwn(incoming, key))
56:           .map((key) => [key, null]);
57:         return [field, Object.fromEntries([...removed, ...Object.entries(incoming)])];
58:       }
59:       return [field, Array.isArray(value) ? [...value] : value];
60:     }),
61:   );
62: }
