1870: /** Minimal shell-like splitter — supports quoted segments. */
1871: function splitArgs(input: string): string[] {
1872:   const out: string[] = [];
1873:   let cur = "";
1874:   let quote: '"' | "'" | null = null;
1875:   for (let i = 0; i < input.length; i++) {
1876:     const ch = input[i];
1877:     if (quote) {
1878:       if (ch === quote) quote = null;
1879:       else cur += ch;
1880:     } else if (ch === '"' || ch === "'") {
1881:       quote = ch;
1882:     } else if (/\s/.test(ch)) {
1883:       if (cur) {
1884:         out.push(cur);
1885:         cur = "";
1886:       }
1887:     } else {
1888:       cur += ch;
1889:     }
1890:   }
1891:   if (cur) out.push(cur);
1892:   return out;
1893: }
